                                    {
                                        "content": "First task",
                                        "status": "in_progress",
                                        "activeForm": "Working on first task",
                                    },
                                ]
                            },
                            "id": "call_write_todos_1",
                            "type": "tool_call",
                        },
                        {
                            "name": "write_todos",
                            "args": {
                                "todos": [
                                    {
                                        "content": "First task",
                                        "status": "completed",
                                        "activeForm": "Working on first task",
                                    },
                                    {
                                        "content": "Second task",
                                        "status": "pending",
                                        "activeForm": "Working on second task",
                                    },
